import warnings
from robot.errors import ExecutionFailed


def args_to_table(args, values=2):
    parsed_data = []
    for num in range(0, len(args), values):
        try:
            data_set = args[num:num + values]
            data_set_size = len(data_set)
            assert data_set_size == values
            if data_set_size == 1:
                parsed_data.append(data_set[0])
            else:
                parsed_data.append(data_set)
        except AssertionError:
            warnings.warn('Data subsets are incomplete or inconsistent')

    return parsed_data


def parse_counters_with_names(args):
    parsed_expectations = []
    expectations_table = args_to_table(args, values=3)
    for counter_id, expectations, name in expectations_table:
        parsed_expectations.append({'counter_id': counter_id, 'expectations': expectations, 'name': name})
    return parsed_expectations


class CounterVerifier(object):
    def __init__(self, expectation_parser, values_fetcher, evaluator, result_logger):
        self.expectation_parser = expectation_parser
        self.values_fetcher = values_fetcher
        self.evaluator = evaluator
        self.results_logger = result_logger

        self.counters_data = []
        self.pass_flag = False

    def parse_expectations(self, args):
        self.counters_data = self.expectation_parser(args)

    def get_all_counters_values(self):
        self._add_counters_data('value', self.values_fetcher.get_all_counters_values(self.counters_data))

    def get_last_counters_values(self):
        self._add_counters_data('value', self.values_fetcher.get_last_counters_values(self.counters_data))

    def verify_counters_values(self):
        self._add_counters_data('result', self.evaluator.evaluate_counters(self.counters_data))
        self.pass_flag = self.evaluator.make_verdict()

    def log_verification_results(self):
        self.results_logger(self.counters_data)

    def apply_verdict(self, continue_on_failure=True):
        if not self.pass_flag:
            raise ExecutionFailed(message="Counters should be true", continue_on_failure=continue_on_failure)

    def _add_counters_data(self, name, data_list):
        for item, new_data in zip(self.counters_data, data_list):
            item.update({name: new_data})
